  "kaynak": "Shao Jing (邵晶), 「石峁遗址与陶寺遗址的比较研究」, Kaogu 2020(5); CSSN özeti, 24.07.2020 · https://www.cssn.cn/lsx/lsx_kgx/202210/t20221024_5552726.shtml",
