  "kaynak": "ARCANE III Tablo 39 s. 136: Ibbisuen 24 yıl 2026-2003 (MC) · http://www.assyriologie.uni-muenchen.de/personen/professoren/sallaberger/publ_sallaberger/wasa_schrakamp_2015_arcane1.pdf",
  "kesinlik": "onyil",
