  "kaynak": "Meier JS, Goring-Morris AN, Munro ND 2016, PLoS One 11(11):e0166573, Tablo 1 (Guney Levant, +-50-100 yil; cal BP->MO: BP-1950) · https://pmc.ncbi.nlm.nih.gov/articles/PMC5130218/",
