  "kaynak": "Benz M, Gresky J, Štefanisko D vd. 2019, PLoS One 14(8):e0221171, doi 10.1371/journal.pone.0221171 · https://pmc.ncbi.nlm.nih.gov/articles/PMC6713438/",
